Consider a causal DAG $\g=(\mathbf{V},\mathbf{E})$, let $\mathbf{V}$ follow a causal linear model compatible with $\g$ and let $\boldsymbol{\epsilon}= \{\epsilon_{v_1},\dots, \epsilon_{v_p}\}$ be the set of errors from the underlying causal linear model. Given a node $A$ and a node set $\mathbf{W}=\{W_1,\dots,W_k\}$, such that $A \notin \mathbf{W}$, the residual $\delta_{a\mathbf{w}}$ is a function of some minimally sized subset $\boldsymbol{\epsilon}^{a\mathbf{w}}$ of $\boldsymbol{\epsilon}$. 
\begin{enumerate}
	\item Let $M \in \mathbf{W}$. If $\epsilon_m \in \boldsymbol{\epsilon}^{a\mathbf{w}}$, then there exists a path of the form 
	$
	A \dots \rightarrow M,
	$
	that is open given $\mathbf{W}$.  \label{in}
	\item Let $M \notin \mathbf{W}$. If $\epsilon_m \in \boldsymbol{\epsilon}^{a\mathbf{w}}$, then there exists  a directed path from $M$ to some node $M' \in (\{A\} \cup \mathbf{W})$ that is open given $\{A\} \cup \mathbf{W}$ and $\epsilon_{m'} \in \epsilon^{a\mathbf{w}}$. Consequentially, there exists a path from $A$ to $M$ that is open given $\mathbf{W}$.
	 \label{out}		






\end{enumerate}
\label{open}

	We first give some preparatory thoughts on how to write $\delta_{a\mathbf{w}}$ as a function in the errors from the causal linear model. Consider a random vector $\mathbf{V}$ that follows a causal linear model compatible with a causal DAG $\g=(\mathbf{V},\mathbf{E})$ and fix some node $V_i \in \mathbf{V}$. 







	We can then write $V_i$ as a linear function of the generating errors in the following way:
	\begin{align}
	V_i = \sum_{V_j \in \mathbf{V}} \tau_{v_iv_j} \epsilon_{v_j} = \sum_{V_j \in \mathrm{an}(V_i,\g)} \tau_{v_iv_j} \epsilon_{v_j}, \label{error.poly} 
	\end{align}
	where we use the convention that $\tau_{v_iv_i}=1$ for any $V_i \in \mathbf{V}$ and make use of the fact that $\tau_{v_jv_i}=0$, whenever $V_i \notin \mathrm{an}(V_j,\g)$ \citep{SEM1989}. 







	Consider the equation
	\begin{align}
	\delta_{a\mathbf{w}} = A - \sum_{W_i \in \mathbf{W}} \beta_{aw_i.\mathbf{w}_{-i}} W_i. \label{deltas}
	\end{align}





	Applying equation \eqref{error.poly} to the $A$ and the $W_i$ terms in equation \eqref{deltas}, we can write 
	$\delta_{a\mathbf{w}}$ 
	as a linear function in the error terms of the generating causal linear model of the form
	\begin{align}
		\delta_{a\mathbf{w}} = \sum_{V_j \in \mathbf{V}} \gamma_{v_j} \epsilon_{v_j},
		\label{equ-errors}
	\end{align}
	with coefficients $\gamma_{v_j} \in \mathbb{R}$.

	We now prove Statement \eqref{in} by contraposition. So assume that $M \in \mathbf{W}$ and that there exists no path $p$ from $A$ to $M$ whose last edge points into $M$ and which is open given $\mathbf{W}$. We will now show that this implies that $\epsilon_m \notin \boldsymbol{\epsilon}^{a\mathbf{w}}$

	 It is sufficient to show that the coefficient $\gamma_m$ corresponding to $\epsilon_m$ in equation \eqref{equ-errors} is equal to 0. The value of $\gamma_m$ is
	\begin{align}
	\gamma_m = \tau_{am} - \sum_{W_i \in \mathbf{W}} \beta_{aw_i.\mathbf{w}_{-i}} \tau_{w_im}. 
	\label{eq:gamma}
	\end{align}
	Our claim thus follows, if we show that  
	\begin{align*}
	\tau_{am} = \sum_{W_i \in \mathrm{de}(M,\g) \cap \mathbf{W}} \beta_{aw_i.\mathbf{w}_{-i}} \tau_{w_im}, 
	\end{align*}
	where we have simplified the sum by removing those $W_i \in \mathbf{W}$ with $\tau_{w_im}=0$.


	Let $\mathbf{W}'=\mathrm{de}(M,\g) \cap \mathbf{W},\mathbf{W}''=\mathbf{W} \setminus \mathrm{de}(M,\g)$ and $\mathbf{W}'''=\mathrm{pa}(M,\g) \cup \mathbf{W}''$. 
	By construction, $\mathbf{W}'''$ contains all parents of $M$ while containing no  descendants of $M$. It thus follows with Lemma \ref{lemma:alwaysVAS} that $\mathbf{W}'''$ is a valid adjustment set relative to $M$ and any node that is not in $\mathbf{W}'''$. We note that $\mathbf{W}' \cap \mathbf{W}'''=\emptyset$ by construction. Further, $A \notin \mathrm{pa}(M,\g)$ by assumption and hence $A \notin \mathbf{W}'''$. 

	Using the already proven first half of Proposition \ref{avarDAG} to replace the total effects with appropriate regression coefficients and vice versa, it follows that
	\begin{align}
	\tau_{am} &= \beta_{am.\mathbf{w}'''}  \nonumber \\
	&= \beta_{am.\mathbf{w}_{-m}'\mathbf{w}'''} + \sum_{W_i \in \mathbf{W}_{-M}'} \beta_{aw_i.\mathbf{w}_{-w_i}'\mathbf{w}'''} \beta_{w_im.\mathbf{w}'''} \nonumber \\
	&= \sum_{W_i \in \mathbf{W'}} \beta_{aw_i.\mathbf{w}_{-w_i}} \tau_{w_im}.  \nonumber 
