 (Weak union and decomposition property)
	\label{lemma: weak union}
	Let $\mathbf{X},\mathbf{Y}$ and $\mathbf{Z}$ be pairwise disjoint node sets in a DAG $\g$. If $\mathbf{Y} \perp_{\g} \mathbf{Z} | \mathbf{X}$, then for any $\mathbf{Z'} \subseteq \mathbf{Z}$ and $\mathbf{Z''} \subset \mathbf{Z}$ such that $\mathbf{Z'} \cap \mathbf{Z''} = \emptyset$, $\mathbf{Y} \perp_{G} \mathbf{Z''}|\mathbf{Z'} \cup \mathbf{X}$.

 (Contraction property)
	\label{lemma: contraction}
	Let $\mathbf{X},\mathbf{Y},\mathbf{Z}$ and $\mathbf{W}$ be pairwise disjoint node sets in a DAG $\g$. If $\mathbf{X} \perp_{\g} \mathbf{Y} | \mathbf{Z}$ and $\mathbf{X} \perp_{\g} \mathbf{W} | \mathbf{Z} \cup \mathbf{Y}$ then $\mathbf{X} \perp_{\g} \mathbf{Y} \cup \mathbf{W} | \mathbf{Z}$.

Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a causal DAG $\g$, such that $\mathbf{Y} \subseteq \mathrm{de}(\mathbf{X},\g)$ and let $\mathbf{O}=\optb{\g}$. Let $\mathbf{T}$ be a set such that 
$\mathbf{T} \cap (\fb{\g} \cup \mathbf{O}) = \emptyset$. If there exists a valid adjustment set relative to $(\mathbf{X},\mathbf{Y})$ in $\g$, then $\mathbf{Y} \perp_{\g}\mathbf{T}|\mathbf{O} \cup \mathbf{X}$.  
\label{y-separation}

Let $\mathbf{X}$ and $\mathbf{Y}$ be disjoint node sets in a maximal PDAG{} $\g$, such that $\g$ is amenable relative to $(\mathbf{X,Y})$ and let $\g[D]$ be a DAG in $[\g]$. Then
$\fb{\g} = \fb{\g[D]}$.
\label{lemma:forbIsSame}

(\citealp[Cf.\ Lemma~B.1 in][]{zhang2008completeness} and \citealp[Lemma~3.6 in][]{perkovic17})
	Let $X$ and $Y$ be two nodes in a maximal PDAG{} $\g$. If $p$ is a directed causal path from $X$ to $Y$ in $\g$, then a subsequence $\overline{p}$ of $p$ forms an unshielded directed causal path from $X$ to $Y$ in~$\g$.
	\label{lemma:unshielded-analog}

(\citealp[Lemma~7.2][]{maathuis2013generalized} and \citealp[Lemma~B.1][]{perkovic17})
	Let $p =(V_1, \dots , V_k)$ be a possibly causal definite status path in a maximal PDAG{} $\g$. If there is a node $V_i, i \in \{1, \dots, k-1\}$ such that $V_i \rightarrow V_{i+1}$, then $p(V_i, V_k)$ is a causal path in $\g$.
	\label{lemma:unshielded-edges-analog}

